    /** Desktop-only JSON-java Map constructor compatibility for these archived captures.
     * Android wraps a Java-null Map value as JSONObject.NULL; the pinned desktop
     * 20240303 constructor omits that key. Validate the complete original OWNER
     * compiler evidence first, then derive a copy with only that representation
     * changed. This never changes archived bytes or production binding admission. */
    private static JSONObject hostObservationCapture(JSONObject original)throws Exception{
        JSONObject binding=original.getJSONObject("binding"),authorization=binding.getJSONObject("authorization");
        Map<String,Object> compiled=TaskAuthorization.parse(binding.getString("owner")).evidence();
        if(!compiled.containsKey("find_query")||compiled.get("find_query")!=null
                ||!authorization.has("find_query")||authorization.get("find_query")!=JSONObject.NULL)
            throw new IllegalArgumentException("exact archived explicit-null find_query required");
        JSONObject hostAuthorization=new JSONObject(compiled);
        if(hostAuthorization.has("find_query"))
            throw new IllegalArgumentException("pinned desktop Map-null constructor semantics changed");
        JSONObject androidAuthorization=new JSONObject(hostAuthorization.toString()).put("find_query",JSONObject.NULL);
        if(!org.trillionnium.hepta.webprotocol.WebEvidenceBinding.canonical(androidAuthorization).equals(
                org.trillionnium.hepta.webprotocol.WebEvidenceBinding.canonical(authorization)))
            throw new IllegalArgumentException("complete archived original OWNER compiler evidence differs");
        JSONObject result=copy(original);
        result.getJSONObject("binding").getJSONObject("authorization").remove("find_query");
        JSONObject restored=copy(result);
        restored.getJSONObject("binding").getJSONObject("authorization").put("find_query",JSONObject.NULL);
        if(!org.trillionnium.hepta.webprotocol.WebDomCanonical.same(restored,original))
            throw new IllegalArgumentException("host copy changed more than the one null representation");
        if(!"427b3e7743e044dc06643468e976ba0fd47c27b28b21203473fd31738937dc53".equals(
                org.trillionnium.hepta.webprotocol.WebEvidenceBinding.sha256(binding))
                ||!"b56264d8894c3c3946437e9aab857c3ccf8453170396acfbff5e556411da1e69".equals(
                org.trillionnium.hepta.webprotocol.WebEvidenceBinding.sha256(result.getJSONObject("binding"))))
            throw new IllegalArgumentException("exact original and derived host binding hashes required");
        org.trillionnium.hepta.webprotocol.WebTaskPurpose.requireBinding(result.getJSONObject("binding"));
        return result;
    }
    private static boolean hostObservationCaptureRejects(JSONObject original)throws Exception{
        try{hostObservationCapture(original);return false;}
        catch(IllegalArgumentException|org.json.JSONException expected){return true;}
    }
