                    &&proof.getJSONObject("last_observation").getString("app_tree_sha256").equals(after.getString("app_tree_sha256")),
                    "both differing original digests remain in the proof");
            check(input.getBoolean("full_native_fixture_is_synthetic"),"positive full traversal is explicitly synthetic");
            check(originalFirst.getJSONObject("binding").getJSONObject("authorization").has("find_query")
                    &&originalFirst.getJSONObject("binding").getJSONObject("authorization").get("find_query")==JSONObject.NULL
                    &&!first.getJSONObject("binding").getJSONObject("authorization").has("find_query"),
                    "archived Android explicit-null remains; only the host copy uses omitted Java-null");
