            rejected(()->changed.observe(a,changed.observer(a),10000),"native WebView geometry changed");
            check(SystemClock.sleeps==0&&changed.client.calls==2&&waits(changed).isEmpty(),"geometry guard is not weakened into settle success");
            check(changed.service.closedSnapshots==1&&changed.service.openSnapshots==0,"geometry failure releases source");
        });
    }
}
